def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'
    if n == 1:
        if history[0][1] == 'D':
            return 'D'
        return 'C'
    if n == 2:
        if history[0][1] == 'D' and history[1][1] == 'D':
            return 'D'
        return 'C'
    if n == 3:
        if history[0][1] == 'D' and history[1][1] == 'D' and history[2][1] == 'D':
            return 'D'
        return 'C'

    me = [h[0] for h in history]
    opp = [h[1] for h in history]
    last_me = me[-1]
    last_opp = opp[-1]

    opp_c = 0
    for x in opp:
        if x == 'C':
            opp_c += 1
    opp_d = n - opp_c
    opp_c_rate = opp_c / n

    opp_d_last5 = 0
    start = n - 5
    if start < 0:
        start = 0
    for i in range(start, n):
        if opp[i] == 'D':
            opp_d_last5 += 1

    opp_d_last10 = 0
    start = n - 10
    if start < 0:
        start = 0
    for i in range(start, n):
        if opp[i] == 'D':
            opp_d_last10 += 1

    opp_c_streak = 0
    for x in reversed(opp):
        if x == 'C':
            opp_c_streak += 1
        else:
            break

    dd_streak = 0
    for i in range(n - 1, -1, -1):
        if me[i] == 'D' and opp[i] == 'D':
            dd_streak += 1
        else:
            break

    my_d_count = 0
    opp_after_my_d = 0
    for i in range(n - 1):
        if me[i] == 'D':
            my_d_count += 1
            if opp[i + 1] == 'D':
                opp_after_my_d += 1

    if my_d_count > 0:
        ret_rate = opp_after_my_d / my_d_count
    else:
        ret_rate = 0.0

    # In the last few rounds, avoid ending in a punishment spiral;
    # defect only against clearly hostile recent play. The final move
    # (handled above) is already a free defection.
    if n >= 95:
        if opp_d_last10 >= 6 or (opp_d > opp_c and last_opp == 'D'):
            return 'D'
        return 'C'

    # If the opponent has been very aggressive recently, punish hard.
    if opp_d_last10 >= 8:
        # Against a mostly cooperative partner, keep one small chance to
        # re-establish cooperation, but only if this is not already a
        # mutual-defection chain.
        if opp_c_rate > 0.80 and opp_d_last5 <= 1 and dd_streak == 0 and rng.random() < 0.07:
            return 'C'
        return 'D'

    # Short-burst aggression by an otherwise cooperative opponent.
    if opp_d_last5 >= 4 and opp_c_rate < 0.70:
        return 'D'

    if last_opp == 'D':
        # If the opponent is probably retaliating for our previous D,
        # extend a conciliatory move to restore CC if they are nice.
        if n >= 2 and me[-2] == 'D' and opp_c_rate > 0.55 and opp_d_last10 <= 5:
            if rng.random() < 0.75:
                return 'C'

        if last_me == 'D':
            # Mutual defection: repair when the opponent still looks cooperative.
            if opp_c_rate > 0.60 and opp_d_last10 <= 5:
                if dd_streak >= 3:
                    if rng.random() < 0.45:
                        return 'C'
                    return 'D'
                if rng.random() < 0.25:
                    return 'C'
            # If the opponent is mostly hostile, do not keep being exploited.
            if rng.random() < 0.30:
                return 'C'
            return 'D'

        # We cooperated and were exploited.
        # Isolated lapse by a very nice opponent: mostly forgive, sometimes test.
        if opp_c_rate > 0.88 and opp_d_last5 == 1 and opp_d <= 5:
            if rng.random() < 0.25:
                return 'C'
            return 'D'

        # More persistent defecting: punish.
        if opp_d_last10 >= 4:
            return 'D'

        # Default: punish the provocation, with a small chance to remain
        # cooperative against unusually forgiving strategies.
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Opponent cooperated last round.
    if last_me == 'D':
        # We just exploited. If they appear forgiving, exploit more;
        # otherwise return to cooperation to avoid a long conflict.
        if opp_c_rate > 0.75 and opp_d_last10 <= 3:
            if my_d_count >= 3 and ret_rate < 0.25:
                if rng.random() < 0.55:
                    return 'D'
            elif my_d_count >= 2 and opp_after_my_d == 0 and opp_d == 0 and opp_c_streak >= 15 and n >= 35:
                if rng.random() < 0.35:
                    return 'D'
            elif opp_c_rate > 0.93 and opp_d_last10 == 0 and my_d_count >= 2 and opp_after_my_d == 0:
                if rng.random() < 0.10:
                    return 'D'
        return 'C'

    # Mutual cooperation. Preserve it, with low-frequency probing only when
    # the opponent is stable, cooperative, and has not shown strong punishment.
    if opp_c_streak >= 10 and n >= 30:
        if opp_c_rate > 0.95 and opp_d_last10 <= 1:
            if my_d_count >= 3 and ret_rate < 0.25:
                if rng.random() < 0.15:
                    return 'D'
            elif opp_d == 0 and n >= 55:
                if rng.random() < 0.12:
                    return 'D'
        elif opp_c_rate > 0.80 and opp_d_last10 <= 3 and ret_rate < 0.40:
            if rng.random() < 0.04:
                return 'D'

    return 'C'
